UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Suites arithmétiques","subtitle_fr":"Raison constante, terme général, somme.","sections":[{"kind":"prerequisite","title_fr":"Prérequis","eyebrow_fr":"PRÉREQUIS","estimated_minutes":"2","blocks":[{"kind":"paragraph","md":"Une **suite numérique** $(u_n)$ est une famille de nombres indexée par $n \\in \\mathbb{N}$. On note $u_0, u_1, u_2, \\dots$ ou $u_n$ le terme de rang $n$."},{"kind":"checkpoint","title_fr":"Bases","questions":[{"stem_fr":"Si $u_n = 2n+1$, que vaut $u_3$ ?","choices_fr":["5","6","7","8"],"correct_index":2,"explanation_fr":"$u_3 = 2 \\times 3 + 1 = 7$."}]}]},{"kind":"concept","title_fr":"Définition et raison","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une suite est **arithmétique** si l''on passe d''un terme au suivant en **ajoutant toujours le même nombre**, appelé la **raison** $r$."},{"kind":"formula","latex":"u_{n+1} = u_n + r","caption_fr":"Définition par récurrence."},{"kind":"formula","latex":"u_n = u_0 + n \\cdot r \\qquad \\text{ou} \\qquad u_n = u_p + (n-p)\\cdot r","caption_fr":"Terme général : à partir de $u_0$ ou d''un terme $u_p$ quelconque."},{"kind":"example","title_fr":"Identifier la raison","problem_fr":"La suite $3, 7, 11, 15, \\dots$ est-elle arithmétique ? Si oui, donne sa raison.","steps_fr":["$u_1 - u_0 = 7 - 3 = 4$.","$u_2 - u_1 = 11 - 7 = 4$, $u_3 - u_2 = 15 - 11 = 4$.","L''écart est constant : la suite est arithmétique de raison $r = 4$."],"answer_fr":"Arithmétique, $r = 4$."}]},{"kind":"concept","title_fr":"Somme des termes","eyebrow_fr":"SOMME","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"S_n = u_0 + u_1 + \\dots + u_n = (n+1)\\cdot \\frac{u_0 + u_n}{2}","caption_fr":"**Astuce de Gauss** : (nombre de termes) × (premier + dernier) / 2."},{"kind":"example","title_fr":"Calculer une somme","problem_fr":"Calcule $1 + 2 + 3 + \\dots + 100$.","steps_fr":["C''est la suite arithmétique de raison 1, allant de $u_1 = 1$ à $u_{100} = 100$.","Nombre de termes : 100. Premier + dernier : $1+100 = 101$.","$S = 100 \\times \\frac{101}{2} = 5050$."],"answer_fr":"$1 + 2 + \\dots + 100 = 5050$."},{"kind":"try_it","title_fr":"À toi de jouer","problem_fr":"Calcule $2 + 5 + 8 + \\dots + 50$ (raison 3, partant de 2).","hint_fr":"Trouve le nombre de termes $n+1$ avec $u_n = 50$, puis applique la formule.","solution_fr":"$50 = 2 + 3n \\Rightarrow n = 16$, donc 17 termes. $S = 17 \\times (2+50)/2 = 17 \\times 26 = 442$."},{"kind":"checkpoint","title_fr":"Suites arithmétiques","questions":[{"stem_fr":"Quelle est la raison de la suite $5, 9, 13, 17$ ?","choices_fr":["3","4","5","9"],"correct_index":1,"explanation_fr":"Différence entre deux termes consécutifs : $9-5 = 4$."},{"stem_fr":"Si $u_0 = 2$ et $r = 3$, que vaut $u_{10}$ ?","choices_fr":["30","31","32","33"],"correct_index":2,"explanation_fr":"$u_{10} = 2 + 10 \\times 3 = 32$."},{"stem_fr":"Somme de $1 + 2 + \\dots + 10$ ?","choices_fr":["45","50","55","60"],"correct_index":2,"explanation_fr":"$10 \\times 11 / 2 = 55$."}]}]}]}'::jsonb WHERE code = 'arithmetic_seq';

-- ===== geometric_seq =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Suites géométriques","subtitle_fr":"Raison multiplicative, terme général, somme géométrique.","sections":[{"kind":"prerequisite","title_fr":"Prérequis : suites arithmétiques","eyebrow_fr":"PRÉREQUIS","estimated_minutes":"2","blocks":[{"kind":"paragraph","md":"Tu sais reconnaître une suite arithmétique (raison **additive** $r$). Une suite **géométrique** fonctionne de la même manière, mais avec une raison **multiplicative** $q$."},{"kind":"checkpoint","title_fr":"Vocabulaire","questions":[{"stem_fr":"Dans $2, 6, 18, 54$, on multiplie chaque terme par :","choices_fr":["2","3","4","6"],"correct_index":1,"explanation_fr":"$6/2 = 3$, $18/6 = 3$ — raison $q = 3$."}]}]},{"kind":"concept","title_fr":"Définition et terme général","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"u_{n+1} = u_n \\cdot q","caption_fr":"Définition par récurrence — chaque terme = précédent × $q$."},{"kind":"formula","latex":"u_n = u_0 \\cdot q^n","caption_fr":"Terme général."},{"kind":"callout","tone":"warning","title_fr":"Attention si $q = 0$ ou $q = 1$","body_fr":"Si $q = 0$, tous les termes sauf $u_0$ sont nuls. Si $q = 1$, la suite est constante. Les formules de somme ci-dessous **excluent** $q = 1$."},{"kind":"example","title_fr":"Calcul direct","problem_fr":"Soit $(u_n)$ géométrique avec $u_0 = 3$ et $q = 2$. Calcule $u_5$.","steps_fr":["$u_n = u_0 \\cdot q^n$.","$u_5 = 3 \\cdot 2^5 = 3 \\cdot 32 = 96$."],"answer_fr":"$u_5 = 96$."}]},{"kind":"concept","title_fr":"Somme géométrique","eyebrow_fr":"SOMME","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"S_n = u_0 + u_0 q + u_0 q^2 + \\dots + u_0 q^n = u_0 \\cdot \\frac{1 - q^{n+1}}{1 - q} \\quad (q \\ne 1)","caption_fr":"Formule de la somme géométrique."},{"kind":"example","title_fr":"Somme jusqu''à $u_4$","problem_fr":"Calcule $1 + 2 + 4 + 8 + 16$.","steps_fr":["Suite géométrique de premier terme 1 et raison 2, 5 termes.","$S = 1 \\cdot \\frac{1 - 2^5}{1 - 2} = \\frac{1 - 32}{-1} = 31$."],"answer_fr":"31."},{"kind":"checkpoint","title_fr":"Suites géométriques","questions":[{"stem_fr":"Quelle est la raison de $8, 4, 2, 1, 0{,}5$ ?","choices_fr":["1/2","2","−2","4"],"correct_index":0,"explanation_fr":"$4/8 = 1/2$ : on divise par 2 = on multiplie par 1/2."},{"stem_fr":"$u_0 = 1$, $q = 3$. Que vaut $u_4$ ?","choices_fr":["64","81","243","729"],"correct_index":1,"explanation_fr":"$u_4 = 1 \\cdot 3^4 = 81$."},{"stem_fr":"Que vaut $1 + 1/2 + 1/4 + \\dots$ (somme infinie, $|q|<1$) ?","choices_fr":["1","3/2","2","∞"],"correct_index":2,"explanation_fr":"Somme infinie : $u_0/(1-q) = 1/(1-1/2) = 2$."}]}]}]}'::jsonb WHERE code = 'geometric_seq';

-- ===== seq_convergence =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Convergence des suites","subtitle_fr":"Limite finie, divergence, théorèmes de comparaison.","sections":[{"kind":"prerequisite","title_fr":"Prérequis","eyebrow_fr":"PRÉREQUIS","estimated_minutes":"2","blocks":[{"kind":"paragraph","md":"Tu connais le terme général d''une suite arithmétique ($u_n = u_0 + nr$) et géométrique ($u_n = u_0 q^n$). On va maintenant étudier leur **comportement quand $n \\to +\\infty$**."}]},{"kind":"concept","title_fr":"Définition de la limite","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Une suite $(u_n)$ **converge vers** $\\ell$ si $u_n$ se rapproche autant qu''on veut de $\\ell$ pour $n$ assez grand. On note $\\lim_{n\\to+\\infty} u_n = \\ell$."},{"kind":"paragraph","md":"Si la limite n''existe pas (ou est $\\pm\\infty$), la suite **diverge**."},{"kind":"formula","latex":"\\lim_{n\\to+\\infty} \\frac{1}{n} = 0","caption_fr":"Suite de référence : 1, 1/2, 1/3, ... tend vers 0."},{"kind":"callout","tone":"insight","title_fr":"Suites géométriques","body_fr":"$\\lim q^n$ dépend de $q$ : si $|q|<1$, ça tend vers 0 ; si $q>1$, ça tend vers $+\\infty$ ; si $q \\le -1$, ça oscille (pas de limite)."},{"kind":"interactive","widget_type":"sequence_calculator","caption_fr":"Saisis une formule pour $u_n$ et observe son comportement à l''infini."}]},{"kind":"concept","title_fr":"Théorèmes de comparaison","eyebrow_fr":"THÉORÈMES","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Théorème des gendarmes** : si $a_n \\le u_n \\le b_n$ et $a_n, b_n \\to \\ell$, alors $u_n \\to \\ell$."},{"kind":"paragraph","md":"**Théorème de comparaison à l''infini** : si $u_n \\ge v_n$ et $v_n \\to +\\infty$, alors $u_n \\to +\\infty$."},{"kind":"example","title_fr":"Théorème des gendarmes","problem_fr":"Calcule $\\lim_{n\\to+\\infty} \\dfrac{\\sin n}{n}$.","steps_fr":["Pour tout $n$ : $-1 \\le \\sin n \\le 1$.","Donc $-\\dfrac{1}{n} \\le \\dfrac{\\sin n}{n} \\le \\dfrac{1}{n}$.","$-1/n \\to 0$ et $1/n \\to 0$, donc par les gendarmes la limite cherchée vaut $0$."],"answer_fr":"$\\lim \\frac{\\sin n}{n} = 0$."},{"kind":"checkpoint","title_fr":"Limites de suites","questions":[{"stem_fr":"$\\lim 1/n^2$ vaut :","choices_fr":["0","1","∞","n''existe pas"],"correct_index":0,"explanation_fr":"Plus $n$ grandit, plus $1/n^2$ devient petit."},{"stem_fr":"$\\lim (0{,}5)^n$ vaut :","choices_fr":["0","0,5","1","∞"],"correct_index":0,"explanation_fr":"$|q|=0{,}5 < 1$ donc $q^n \\to 0$."},{"stem_fr":"$\\lim 2^n$ vaut :","choices_fr":["0","2","∞","n''existe pas"],"correct_index":2,"explanation_fr":"$q=2>1$ donc la suite diverge vers $+\\infty$."},{"stem_fr":"Le théorème des gendarmes sert à :","choices_fr":["démontrer une convergence par encadrement","calculer une dérivée","résoudre une équation","rien de spécial"],"correct_index":0,"explanation_fr":"On encadre la suite entre deux suites de même limite."}]}]}]}'::jsonb WHERE code = 'seq_convergence';

-- ===== seq_recursive =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Suites récurrentes","subtitle_fr":"Étudier $u_{n+1} = f(u_n)$ — variations, convergence vers un point fixe.","sections":[{"kind":"prerequisite","title_fr":"Prérequis","eyebrow_fr":"PRÉREQUIS","estimated_minutes":"2","blocks":[{"kind":"paragraph","md":"On suppose $f$ continue, et on étudie une suite définie par $u_0 \\in I$ et $u_{n+1} = f(u_n)$. L''objectif : décrire le comportement de $(u_n)$."}]},{"kind":"concept","title_fr":"Méthode standard en 4 étapes","eyebrow_fr":"MÉTHODE","estimated_minutes":"6","blocks":[{"kind":"paragraph","md":"**Étape 1** — Vérifier que $(u_n)$ reste dans un intervalle stable $I$ (récurrence : si $u_n \\in I$ alors $f(u_n) \\in I$)."},{"kind":"paragraph","md":"**Étape 2** — Étudier la **monotonie** : signe de $u_{n+1} - u_n$ ou comparaison de $f(x)$ et $x$."},{"kind":"paragraph","md":"**Étape 3** — Si $(u_n)$ est monotone et bornée, elle **converge** (théorème de la limite monotone)."},{"kind":"paragraph","md":"**Étape 4** — La limite $\\ell$ est un **point fixe** de $f$ : $\\ell = f(\\ell)$. Résoudre cette équation."},{"kind":"interactive","widget_type":"recurrence_solver","caption_fr":"Saisis $f(x)$ et $u_0$ — visualise la convergence en escalier."}]},{"kind":"exampleWalkthrough","title_fr":"Exemple complet","eyebrow_fr":"EXEMPLE","estimated_minutes":"5","blocks":[{"kind":"example","title_fr":"Étude de $u_{n+1} = \\sqrt{u_n + 2}$, $u_0 = 0$","problem_fr":"Étudier la suite $u_{n+1} = \\sqrt{u_n + 2}$ avec $u_0 = 0$.","steps_fr":["On vérifie que $(u_n)$ reste dans $[0, 2]$ par récurrence.","Étude de la monotonie : $u_1 = \\sqrt{2} \\approx 1{,}41 > u_0 = 0$ — la suite semble croissante. On le démontre par récurrence : si $u_n \\le u_{n+1}$ alors $u_n + 2 \\le u_{n+1} + 2$, et $\\sqrt{}$ étant croissante, $u_{n+1} \\le u_{n+2}$.","La suite est croissante et majorée par 2 → elle converge vers $\\ell$ avec $0 \\le \\ell \\le 2$.","Point fixe : $\\ell = \\sqrt{\\ell + 2} \\Leftrightarrow \\ell^2 = \\ell + 2 \\Leftrightarrow \\ell^2 - \\ell - 2 = 0\\Leftrightarrow (\\ell-2)(\\ell+1) = 0$.","Comme $\\ell \\ge 0$, on retient $\\ell = 2$."],"answer_fr":"$(u_n)$ converge vers 2."},{"kind":"checkpoint","title_fr":"Récurrentes","questions":[{"stem_fr":"Si $f$ est continue et $u_n \\to \\ell$, alors :","choices_fr":["$\\ell = 0$","$\\ell = u_0$","$\\ell = f(\\ell)$","$\\ell = +\\infty$"],"correct_index":2,"explanation_fr":"Par continuité, on passe à la limite dans $u_{n+1} = f(u_n)$ : $\\ell = f(\\ell)$."},{"stem_fr":"Pour conclure à la convergence d''une suite récurrente, on cherche typiquement à montrer qu''elle est :","choices_fr":["arithmétique","majorée seulement","monotone et bornée","oscillante"],"correct_index":2,"explanation_fr":"Théorème de la limite monotone."}]}]}]}'::jsonb WHERE code = 'seq_recursive';

-- ===== seq_adjacent =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Suites adjacentes","subtitle_fr":"Définition, théorème et applications.","sections":[{"kind":"concept","title_fr":"Définition","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Deux suites $(u_n)$ et $(v_n)$ sont **adjacentes** si :"},{"kind":"paragraph","md":"• $(u_n)$ est croissante,"},{"kind":"paragraph","md":"• $(v_n)$ est décroissante,"},{"kind":"paragraph","md":"• $\\lim (v_n - u_n) = 0$."},{"kind":"callout","tone":"insight","title_fr":"Théorème des suites adjacentes","body_fr":"Si $(u_n)$ et $(v_n)$ sont adjacentes, alors elles **convergent vers la même limite** $\\ell$, et de plus $u_n \\le \\ell \\le v_n$ pour tout $n$."}]},{"kind":"exampleWalkthrough","title_fr":"Exemple type","eyebrow_fr":"EXEMPLE","estimated_minutes":"4","blocks":[{"kind":"example","title_fr":"Approximation de $\\sqrt{2}$","problem_fr":"Soit $u_n$ et $v_n$ deux suites construites par dichotomie autour de $\\sqrt{2}$. Montre qu''elles sont adjacentes et déduis-en $\\sqrt{2}$.","steps_fr":["Par construction, $u_n$ est croissante et $v_n$ décroissante.","À chaque étape on divise l''écart par 2 : $v_n - u_n = (v_0 - u_0)/2^n \\to 0$.","Donc $(u_n)$ et $(v_n)$ sont adjacentes : elles convergent vers une même limite $\\ell$.","$\\ell$ est l''unique solution dans $[u_0, v_0]$ de $x^2 = 2$ : $\\ell = \\sqrt{2}$."],"answer_fr":"$(u_n)$ et $(v_n)$ convergent vers $\\sqrt{2}$."},{"kind":"checkpoint","title_fr":"Adjacentes","questions":[{"stem_fr":"Si $(u_n)$ croissante, $(v_n)$ décroissante et $v_n - u_n \\to 0$, alors :","choices_fr":["elles divergent","elles ont la même limite","elles sont égales","elles tendent vers 0"],"correct_index":1,"explanation_fr":"C''est le théorème des suites adjacentes."}]}]}]}'::jsonb WHERE code = 'seq_adjacent';

-- ===== limit_def =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Notion de limite","subtitle_fr":"L''idée de « tendre vers » et la limite finie.","sections":[{"kind":"concept","title_fr":"Idée intuitive","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Pour la fonction $f(x) = \\frac{x^2 - 4}{x - 2}$, on peut calculer $f$ pour $x$ proche de 2 (mais $\\ne 2$, car le dénominateur s''annule en 2)."},{"kind":"paragraph","md":"Pour $x = 1{,}9$ : $f(x) = 3{,}9$. Pour $x = 1{,}99$ : $f(x) = 3{,}99$. Plus $x$ s''approche de 2, plus $f(x)$ s''approche de 4."},{"kind":"formula","latex":"\\lim_{x\\to a} f(x) = L","caption_fr":"« $f(x)$ tend vers $L$ quand $x$ tend vers $a$ »."},{"kind":"interactive","widget_type":"function_graph","config":{"function":"(x*x - 4) / (x - 2)"},"caption_fr":"Observe que $f(x)$ approche 4 sans que $x = 2$."}]},{"kind":"concept","title_fr":"Trois cas possibles","eyebrow_fr":"CAS","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"**1. Limite finie** : $f(x) \\to L$ avec $L$ un nombre."},{"kind":"paragraph","md":"**2. Limite infinie** : $f(x) \\to +\\infty$ ou $-\\infty$."},{"kind":"paragraph","md":"**3. Pas de limite** : $f(x)$ n''approche aucune valeur (oscille, etc.)."},{"kind":"example","title_fr":"Substitution directe","problem_fr":"$\\lim_{x \\to 3}(x^2 + 1) = ?$","steps_fr":["La fonction $x^2 + 1$ est un polynôme, continue partout.","On substitue : $3^2 + 1 = 10$."],"answer_fr":"10."},{"kind":"checkpoint","title_fr":"Limites — bases","questions":[{"stem_fr":"$\\lim_{x\\to 0} x^2 = ?$","choices_fr":["0","1","∞","n''existe pas"],"correct_index":0,"explanation_fr":"Substitution directe : $0^2 = 0$."},{"stem_fr":"$\\lim_{x\\to +\\infty} \\frac{1}{x} = ?$","choices_fr":["0","1","∞","−∞"],"correct_index":0,"explanation_fr":"$1/x$ devient infiniment petit quand $x \\to +\\infty$."}]}]}]}'::jsonb WHERE code = 'limit_def';

-- ===== limit_calc =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Calcul de limites","subtitle_fr":"Substitution, formes indéterminées, factorisation et conjugué.","sections":[{"kind":"concept","title_fr":"Les 4 outils essentiels","eyebrow_fr":"OUTILS","estimated_minutes":"6","blocks":[{"kind":"paragraph","md":"**1. Substitution directe** — si $f$ est continue, $\\lim_{x\\to a} f(x) = f(a)$. Toujours essayer en premier."},{"kind":"paragraph","md":"**2. Forme $0/0$** — factorise et simplifie."},{"kind":"paragraph","md":"**3. Forme $\\infty/\\infty$** — divise haut et bas par la plus haute puissance."},{"kind":"paragraph","md":"**4. Multiplication par le conjugué** — quand il y a une racine carrée."},{"kind":"formula","latex":"\\lim(f \\pm g) = \\lim f \\pm \\lim g, \\quad \\lim(fg) = \\lim f \\cdot \\lim g, \\quad \\lim(f/g) = \\lim f / \\lim g","caption_fr":"Opérations sur les limites (sous condition que les limites existent)."},{"kind":"interactive","widget_type":"limit_calculator","caption_fr":"Saisis une expression et observe sa limite."}]},{"kind":"exampleWalkthrough","title_fr":"Trois exemples-clés","eyebrow_fr":"EXEMPLES","estimated_minutes":"6","blocks":[{"kind":"example","title_fr":"Forme 0/0","problem_fr":"$\\lim_{x\\to 2} \\dfrac{x^2 - 4}{x - 2}$","steps_fr":["Substitution : $0/0$, indéterminé.","Factorise : $x^2 - 4 = (x-2)(x+2)$.","Simplifie : $\\frac{(x-2)(x+2)}{x-2} = x + 2$.","Limite : $\\lim_{x\\to 2}(x+2) = 4$."],"answer_fr":"4."},{"kind":"example","title_fr":"Forme ∞/∞","problem_fr":"$\\lim_{x\\to +\\infty} \\dfrac{2x^2 + 3}{x^2 - 1}$","steps_fr":["Forme $\\infty/\\infty$.","Divise haut/bas par $x^2$ : $\\frac{2 + 3/x^2}{1 - 1/x^2}$.","À l''infini : $\\frac{2 + 0}{1 - 0} = 2$."],"answer_fr":"2."},{"kind":"try_it","title_fr":"À toi","problem_fr":"Calcule $\\lim_{x\\to 1} \\dfrac{x^2 - 1}{x - 1}$.","hint_fr":"C''est une forme $0/0$ — factorise.","solution_fr":"$x^2 - 1 = (x-1)(x+1)$, donc la limite vaut $1+1 = 2$."},{"kind":"checkpoint","title_fr":"Calcul de limites","questions":[{"stem_fr":"$\\lim_{x\\to 4} \\frac{x^2-16}{x-4} = ?$","choices_fr":["0","4","8","16"],"correct_index":2,"explanation_fr":"Factorise $x^2-16 = (x-4)(x+4)$ → $x+4 \\to 8$."},{"stem_fr":"$\\lim_{x\\to +\\infty} \\frac{3x+1}{x+5} = ?$","choices_fr":["0","1","3","∞"],"correct_index":2,"explanation_fr":"Même degré, rapport des coefficients dominants = 3."},{"stem_fr":"$\\lim_{x\\to 0^+} \\frac{1}{x} = ?$","choices_fr":["0","+∞","−∞","n''existe pas"],"correct_index":1,"explanation_fr":"À droite de 0, $1/x$ tend vers $+\\infty$."}]}]}]}'::jsonb WHERE code = 'limit_calc';

-- ===== continuity =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Continuité","subtitle_fr":"Définition et fonctions usuelles.","sections":[{"kind":"concept","title_fr":"Définition formelle","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"f \\text{ continue en } a \\iff \\lim_{x\\to a} f(x) = f(a)","caption_fr":"**La limite en $a$ coïncide avec la valeur en $a$**."},{"kind":"paragraph","md":"Géométriquement : la courbe se trace sans lever le crayon. Pas de saut, pas de trou."},{"kind":"callout","tone":"note","title_fr":"Fonctions continues partout","body_fr":"Polynômes, sinus, cosinus, exponentielle sont continues sur $\\mathbb{R}$. $1/x$ est continue sur $\\mathbb{R}^*$ (mais pas définie en 0)."}]},{"kind":"concept","title_fr":"Continuité sur un intervalle","eyebrow_fr":"INTERVALLE","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"$f$ est continue sur $[a,b]$ si elle est continue en chaque point de l''intervalle. Cette propriété est cruciale pour le **TVI** (chapitre suivant)."},{"kind":"example","title_fr":"Étude de continuité","problem_fr":"$f(x) = \\begin{cases} x^2 \\text{ si } x \\le 1 \\\\ 2x - 1 \\text{ si } x > 1\\end{cases}$. Est-elle continue en 1 ?","steps_fr":["$\\lim_{x\\to 1^-} f(x) = 1^2 = 1$.","$\\lim_{x\\to 1^+} f(x) = 2 \\cdot 1 - 1 = 1$.","Les deux limites coïncident avec $f(1) = 1$.","Donc $f$ est continue en 1."],"answer_fr":"Oui, continue en 1."},{"kind":"checkpoint","title_fr":"Continuité","questions":[{"stem_fr":"$f$ continue en $a$ signifie :","choices_fr":["$f(a) = 0$","$\\lim_{x\\to a} f(x) = f(a)$","$f$ dérivable","$f$ croissante"],"correct_index":1,"explanation_fr":"Définition exacte de la continuité."},{"stem_fr":"Quelle fonction n''est PAS continue sur $\\mathbb{R}$ ?","choices_fr":["$\\sin x$","$x^2$","$1/x$","$e^x$"],"correct_index":2,"explanation_fr":"$1/x$ n''est pas définie en 0."}]}]}]}'::jsonb WHERE code = 'continuity';

-- ===== tvi =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Théorème des valeurs intermédiaires","subtitle_fr":"Garantir l''existence d''une solution sans la calculer.","sections":[{"kind":"concept","title_fr":"Énoncé du TVI","eyebrow_fr":"THÉORÈME","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\text{Si } f \\text{ continue sur } [a,b] \\text{ et } k \\text{ entre } f(a) \\text{ et } f(b) \\text{, alors } \\exists c \\in [a,b] : f(c) = k.","caption_fr":"Énoncé du TVI."},{"kind":"paragraph","md":"**Cas particulier ultra-utile** : si $f(a) \\cdot f(b) < 0$ (signes opposés), alors $f$ s''annule au moins une fois sur $]a, b[$."},{"kind":"callout","tone":"warning","title_fr":"Le TVI ne donne PAS la valeur de $c$","body_fr":"Il garantit qu''une solution existe, sans la calculer. Pour la trouver, il faut une autre méthode (calcul ou dichotomie)."}]},{"kind":"exampleWalkthrough","title_fr":"Application classique","eyebrow_fr":"EXEMPLE","estimated_minutes":"5","blocks":[{"kind":"example","title_fr":"Existence d''une solution","problem_fr":"Montre que $x^3 + x - 1 = 0$ admet une solution dans $]0, 1[$.","steps_fr":["Pose $f(x) = x^3 + x - 1$. $f$ est un polynôme, donc continue sur $[0, 1]$.","$f(0) = -1 < 0$.","$f(1) = 1 + 1 - 1 = 1 > 0$.","$f(0) \\cdot f(1) < 0$, donc par le TVI il existe $c \\in ]0, 1[$ tel que $f(c) = 0$."],"answer_fr":"L''équation admet une solution dans $]0, 1[$."},{"kind":"try_it","title_fr":"À toi","problem_fr":"Montre que $\\cos(x) = x$ admet une solution dans $[0, \\pi/2]$.","hint_fr":"Pose $g(x) = \\cos(x) - x$, et calcule $g(0)$ et $g(\\pi/2)$.","solution_fr":"$g(0) = 1 - 0 = 1 > 0$. $g(\\pi/2) = 0 - \\pi/2 < 0$. $g$ est continue sur $[0, \\pi/2]$, donc par le TVI il existe une solution."},{"kind":"checkpoint","title_fr":"TVI","questions":[{"stem_fr":"Le TVI permet de :","choices_fr":["calculer une solution exacte","garantir l''existence d''une solution","trouver une asymptote","dériver une fonction"],"correct_index":1,"explanation_fr":"Le TVI prouve l''existence sans donner la valeur."},{"stem_fr":"$f$ continue sur $[0,1]$, $f(0) = 3$, $f(1) = -2$. Le TVI garantit qu''il existe $c$ tel que :","choices_fr":["$f(c) = 5$","$f(c) = 0$","$f(c) = -3$","$f(c) = 4$"],"correct_index":1,"explanation_fr":"0 est entre $f(0) = 3$ et $f(1) = -2$, donc $\\exists c : f(c) = 0$."}]}]}]}'::jsonb WHERE code = 'tvi';

-- ===== deriv_basic =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Dérivées de base","subtitle_fr":"Dérivée en un point, fonction dérivée, formules à connaître.","sections":[{"kind":"concept","title_fr":"Définition de la dérivée","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"f''(a) = \\lim_{h\\to 0} \\frac{f(a+h) - f(a)}{h}","caption_fr":"Définition formelle : limite du **taux d''accroissement**."},{"kind":"paragraph","md":"Géométriquement, $f''(a)$ est la **pente de la tangente** à la courbe en $a$."},{"kind":"interactive","widget_type":"derivative_graph","caption_fr":"Bouge le point — observe que la pente de la tangente = $f''(a)$."}]},{"kind":"concept","title_fr":"Formules à mémoriser","eyebrow_fr":"FORMULES","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"(x^n)'' = n x^{n-1} \\quad (\\sqrt{x})'' = \\frac{1}{2\\sqrt{x}} \\quad (1/x)'' = -1/x^2","caption_fr":"Dérivées des fonctions de référence."},{"kind":"formula","latex":"(\\sin x)'' = \\cos x \\quad (\\cos x)'' = -\\sin x \\quad (e^x)'' = e^x \\quad (\\ln x)'' = 1/x","caption_fr":"Trigo, exp, ln."},{"kind":"example","title_fr":"Calcul direct","problem_fr":"Dérive $f(x) = x^3 + 2x$.","steps_fr":["$(x^3)'' = 3x^2$, $(2x)'' = 2$ — d''où $f''(x) = 3x^2 + 2$."],"answer_fr":"$f''(x) = 3x^2 + 2$."},{"kind":"checkpoint","title_fr":"Bases","questions":[{"stem_fr":"$(x^4)'' = ?$","choices_fr":["$x^3$","$3x^3$","$4x^3$","$4x^4$"],"correct_index":2,"explanation_fr":"$n x^{n-1} = 4x^3$."},{"stem_fr":"$(\\sin x)'' = ?$","choices_fr":["$\\sin x$","$\\cos x$","$-\\cos x$","$-\\sin x$"],"correct_index":1,"explanation_fr":"Formule de référence."},{"stem_fr":"$(e^x)'' = ?$","choices_fr":["$x e^{x-1}$","$e^x$","$e^{x+1}$","$1$"],"correct_index":1,"explanation_fr":"L''exponentielle est sa propre dérivée."}]}]}]}'::jsonb WHERE code = 'deriv_basic';

-- ===== deriv_rules =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Règles de dérivation","subtitle_fr":"Somme, produit, quotient, composition.","sections":[{"kind":"concept","title_fr":"Les 4 règles","eyebrow_fr":"RÈGLES","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"(u + v)'' = u'' + v'' \\qquad (\\lambda u)'' = \\lambda u''","caption_fr":"Linéarité."},{"kind":"formula","latex":"(uv)'' = u''v + uv''","caption_fr":"Produit."},{"kind":"formula","latex":"\\left(\\dfrac{u}{v}\\right)'' = \\dfrac{u''v - uv''}{v^2}","caption_fr":"Quotient ($v \\ne 0$)."},{"kind":"formula","latex":"(u(v(x)))'' = v''(x) \\cdot u''(v(x))","caption_fr":"Composition (chain rule)."},{"kind":"interactive","widget_type":"chain_rule_visualizer","caption_fr":"Visualise comment la dérivée d''une composée se construit."}]},{"kind":"exampleWalkthrough","title_fr":"Trois calculs typiques","eyebrow_fr":"EXEMPLES","estimated_minutes":"5","blocks":[{"kind":"example","title_fr":"Produit","problem_fr":"Dérive $f(x) = x^2 \\sin x$.","steps_fr":["Pose $u = x^2$, $v = \\sin x$. Alors $u'' = 2x$, $v'' = \\cos x$.","$f'' = u''v + uv'' = 2x \\sin x + x^2 \\cos x$."],"answer_fr":"$f''(x) = 2x \\sin x + x^2 \\cos x$."},{"kind":"example","title_fr":"Quotient","problem_fr":"Dérive $g(x) = \\dfrac{x}{x^2 + 1}$.","steps_fr":["$u = x$, $v = x^2 + 1$ : $u'' = 1$, $v'' = 2x$.","$g'' = \\frac{u''v - uv''}{v^2} = \\frac{(x^2+1) - x(2x)}{(x^2+1)^2} = \\frac{1 - x^2}{(x^2+1)^2}$."],"answer_fr":"$g''(x) = \\dfrac{1 - x^2}{(x^2+1)^2}$."},{"kind":"checkpoint","title_fr":"Règles","questions":[{"stem_fr":"$(x \\cdot e^x)'' = ?$","choices_fr":["$e^x$","$x e^x$","$(1+x) e^x$","$xe^x + 1$"],"correct_index":2,"explanation_fr":"Produit : $(1)(e^x) + (x)(e^x) = (1+x)e^x$."},{"stem_fr":"$(\\cos(2x))'' = ?$","choices_fr":["$-\\sin(2x)$","$-2\\sin(2x)$","$2\\cos(2x)$","$-\\cos(2x)$"],"correct_index":1,"explanation_fr":"Composition : $2 \\cdot (-\\sin(2x))$."}]}]}]}'::jsonb WHERE code = 'deriv_rules';

-- ===== deriv_apps =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Applications de la dérivée","subtitle_fr":"Tangente, sens de variation, extrema.","sections":[{"kind":"concept","title_fr":"Équation de la tangente","eyebrow_fr":"TANGENTE","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"y = f''(a)(x - a) + f(a)","caption_fr":"Équation de la tangente à la courbe en $x = a$."},{"kind":"example","title_fr":"Tangente à la parabole","problem_fr":"Tangente à $y = x^2$ au point $x = 1$.","steps_fr":["$f(1) = 1$, $f''(x) = 2x$, $f''(1) = 2$.","$y = 2(x - 1) + 1 = 2x - 1$."],"answer_fr":"$y = 2x - 1$."}]},{"kind":"concept","title_fr":"Sens de variation","eyebrow_fr":"VARIATION","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Le signe de $f''$ donne le sens de variation de $f$.**"},{"kind":"paragraph","md":"• $f'' > 0$ sur $I$ : $f$ est strictement croissante sur $I$."},{"kind":"paragraph","md":"• $f'' < 0$ sur $I$ : $f$ est strictement décroissante sur $I$."},{"kind":"paragraph","md":"• $f''(a) = 0$ avec changement de signe : $f$ a un **extremum** en $a$."},{"kind":"interactive","widget_type":"sign_table","caption_fr":"Construis le tableau de signes — déduis-en le tableau de variations."}]},{"kind":"exampleWalkthrough","title_fr":"Étude type","eyebrow_fr":"EXEMPLE","estimated_minutes":"5","blocks":[{"kind":"example","title_fr":"Étude des variations","problem_fr":"Étudie le sens de variation de $f(x) = x^3 - 3x$.","steps_fr":["$f''(x) = 3x^2 - 3 = 3(x-1)(x+1)$.","Signe : positif sur $]-\\infty, -1[$ ∪ $]1, +\\infty[$, négatif sur $]-1, 1[$.","Donc $f$ est croissante sur $]-\\infty, -1]$, décroissante sur $[-1, 1]$, croissante sur $[1, +\\infty[$.","Maximum local en $x=-1$ : $f(-1) = 2$. Minimum local en $x=1$ : $f(1) = -2$."],"answer_fr":"Variations alternées avec extrema en $\\pm 1$."},{"kind":"checkpoint","title_fr":"Variations","questions":[{"stem_fr":"Si $f''(a) = 0$ avec changement de signe $+ \\to -$ :","choices_fr":["minimum","maximum","rien","point d''inflexion"],"correct_index":1,"explanation_fr":"$f$ croît puis décroît → maximum."},{"stem_fr":"Tangente à $y = x^3$ en $x=2$ a pour équation :","choices_fr":["$y = 12x - 16$","$y = 6x$","$y = 12x$","$y = 8x$"],"correct_index":0,"explanation_fr":"$f(2)=8$, $f''(x)=3x^2$, $f''(2)=12$. Tangente : $y = 12(x-2) + 8 = 12x - 16$."}]}]}]}'::jsonb WHERE code = 'deriv_apps';

-- ===== primitives =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Primitives","subtitle_fr":"Inverser la dérivation : trouver $F$ telle que $F'' = f$.","sections":[{"kind":"concept","title_fr":"Définition","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une **primitive** de $f$ sur un intervalle $I$ est une fonction $F$ telle que $F''(x) = f(x)$ pour tout $x \\in I$."},{"kind":"callout","tone":"insight","title_fr":"Unicité à une constante près","body_fr":"Si $F$ est une primitive de $f$, alors $F + c$ aussi (pour toute constante $c$). Toutes les primitives diffèrent d''une constante."}]},{"kind":"concept","title_fr":"Tableau des primitives usuelles","eyebrow_fr":"FORMULES","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\int x^n \\, dx = \\frac{x^{n+1}}{n+1} + c \\quad (n \\ne -1)","caption_fr":"Puissances."},{"kind":"formula","latex":"\\int \\frac{1}{x} \\, dx = \\ln |x| + c","caption_fr":"Cas $n = -1$."},{"kind":"formula","latex":"\\int e^x \\, dx = e^x + c, \\quad \\int \\sin x\\, dx = -\\cos x + c, \\quad \\int \\cos x \\, dx = \\sin x + c","caption_fr":"Exp et trigo."},{"kind":"example","title_fr":"Trouver une primitive","problem_fr":"Trouve une primitive de $f(x) = 3x^2 + 1$.","steps_fr":["$\\int 3x^2 dx = x^3$ et $\\int 1 dx = x$.","Donc $F(x) = x^3 + x + c$."],"answer_fr":"$F(x) = x^3 + x + c$."},{"kind":"checkpoint","title_fr":"Primitives","questions":[{"stem_fr":"Une primitive de $2x$ est :","choices_fr":["$x^2$","$x$","$2$","$x^3/3$"],"correct_index":0,"explanation_fr":"$(x^2)'' = 2x$."},{"stem_fr":"Une primitive de $\\cos x$ est :","choices_fr":["$\\sin x$","$-\\sin x$","$\\cos x$","$-\\cos x$"],"correct_index":0,"explanation_fr":"$(\\sin x)'' = \\cos x$."},{"stem_fr":"Une primitive de $e^x$ est :","choices_fr":["$x e^x$","$e^x$","$e^{x+1}$","$x$"],"correct_index":1,"explanation_fr":"$e^x$ est sa propre primitive."}]}]}]}'::jsonb WHERE code = 'primitives';

-- ===== definite_integral =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Intégrale définie","subtitle_fr":"Aire sous la courbe et théorème fondamental.","sections":[{"kind":"concept","title_fr":"Théorème fondamental","eyebrow_fr":"THÉORÈME","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\int_a^b f(x) \\, dx = F(b) - F(a)","caption_fr":"où $F$ est **n''importe quelle** primitive de $f$."},{"kind":"paragraph","md":"Cette **intégrale définie** est l''aire algébrique entre la courbe de $f$ et l''axe des abscisses, entre $x = a$ et $x = b$."},{"kind":"interactive","widget_type":"area_curve","caption_fr":"Visualise l''aire sous la courbe."}]},{"kind":"concept","title_fr":"Propriétés à connaître","eyebrow_fr":"PROPRIÉTÉS","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"\\int_a^a f = 0, \\quad \\int_a^b f = -\\int_b^a f, \\quad \\int_a^c f = \\int_a^b f + \\int_b^c f","caption_fr":"Relation de Chasles, antisymétrie."},{"kind":"formula","latex":"\\int_a^b (\\lambda f + \\mu g) = \\lambda \\int_a^b f + \\mu \\int_a^b g","caption_fr":"Linéarité."},{"kind":"example","title_fr":"Calcul direct","problem_fr":"Calcule $\\int_0^1 x^2 \\, dx$.","steps_fr":["Primitive de $x^2$ : $F(x) = x^3/3$.","$F(1) - F(0) = 1/3 - 0 = 1/3$."],"answer_fr":"$1/3$."},{"kind":"checkpoint","title_fr":"Intégrale","questions":[{"stem_fr":"$\\int_0^1 1 \\, dx = ?$","choices_fr":["0","1","$1/2$","$\\infty$"],"correct_index":1,"explanation_fr":"Aire d''un rectangle 1×1."},{"stem_fr":"$\\int_0^\\pi \\sin x \\, dx = ?$","choices_fr":["0","1","2","$\\pi$"],"correct_index":2,"explanation_fr":"$[-\\cos x]_0^\\pi = -(-1) - (-1) = 2$."},{"stem_fr":"Si $F$ est primitive de $f$, alors $\\int_2^5 f = ?$","choices_fr":["$F(5)+F(2)$","$F(5) - F(2)$","$F(2) - F(5)$","$F(5)\\cdot F(2)$"],"correct_index":1,"explanation_fr":"Théorème fondamental."}]}]}]}'::jsonb WHERE code = 'definite_integral';

-- ===== integral_apps =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Calcul d''aires","subtitle_fr":"Aire entre une courbe et l''axe, entre deux courbes.","sections":[{"kind":"concept","title_fr":"Aire sous une courbe positive","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Si $f \\ge 0$ sur $[a, b]$, alors $\\int_a^b f(x) \\, dx$ est **l''aire** (en unités d''aire) entre la courbe et l''axe Ox."},{"kind":"formula","latex":"\\mathcal{A} = \\int_a^b f(x) \\, dx","caption_fr":"Aire géométrique."},{"kind":"callout","tone":"warning","title_fr":"Si $f$ change de signe","body_fr":"L''intégrale est l''aire **algébrique** : positive au-dessus de l''axe, négative en-dessous. Pour l''aire géométrique, utilise $\\int_a^b |f(x)| \\, dx$."}]},{"kind":"concept","title_fr":"Aire entre deux courbes","eyebrow_fr":"COURBES","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"\\mathcal{A} = \\int_a^b (f(x) - g(x)) \\, dx \\quad \\text{si } f \\ge g \\text{ sur } [a, b]","caption_fr":"Aire entre deux courbes."},{"kind":"example","title_fr":"Aire entre y=x et y=x²","problem_fr":"Calcule l''aire entre $y = x$ et $y = x^2$ entre 0 et 1.","steps_fr":["Sur $[0, 1]$ on a $x \\ge x^2$ (sauf aux bornes).","$\\mathcal{A} = \\int_0^1 (x - x^2) \\, dx = [x^2/2 - x^3/3]_0^1 = 1/2 - 1/3 = 1/6$."],"answer_fr":"$1/6$."},{"kind":"checkpoint","title_fr":"Aires","questions":[{"stem_fr":"L''aire de la région entre $y = 1$ et l''axe sur $[0, 4]$ vaut :","choices_fr":["1","2","4","8"],"correct_index":2,"explanation_fr":"Rectangle de hauteur 1 et largeur 4."},{"stem_fr":"Si $f \\le 0$ sur $[a,b]$, alors $\\int_a^b f$ est :","choices_fr":["positive","négative","nulle","indéterminée"],"correct_index":1,"explanation_fr":"$f \\le 0$ donne une intégrale négative."}]}]}]}'::jsonb WHERE code = 'integral_apps';

-- ===== prob_basic =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Probabilités de base","subtitle_fr":"Univers, événements, probabilité uniforme.","sections":[{"kind":"concept","title_fr":"Vocabulaire","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"**Univers** $\\Omega$ : ensemble des résultats possibles d''une expérience aléatoire."},{"kind":"paragraph","md":"**Événement** : sous-ensemble de $\\Omega$. **Événement élémentaire** : un seul résultat."},{"kind":"formula","latex":"P(A) = \\dfrac{\\text{nombre de cas favorables}}{\\text{nombre total de cas}}","caption_fr":"Probabilité **uniforme** (chaque issue équiprobable)."}]},{"kind":"concept","title_fr":"Règles de calcul","eyebrow_fr":"RÈGLES","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"P(\\bar{A}) = 1 - P(A)","caption_fr":"Événement contraire."},{"kind":"formula","latex":"P(A \\cup B) = P(A) + P(B) - P(A \\cap B)","caption_fr":"Réunion d''événements."},{"kind":"example","title_fr":"Lancer de dé","problem_fr":"On lance un dé équilibré. Probabilité d''obtenir un nombre pair ?","steps_fr":["Univers : $\\{1, 2, 3, 4, 5, 6\\}$, 6 issues équiprobables.","Cas favorables : $\\{2, 4, 6\\}$, soit 3.","$P = 3/6 = 1/2$."],"answer_fr":"$1/2$."},{"kind":"checkpoint","title_fr":"Probabilités","questions":[{"stem_fr":"Probabilité de tirer un cœur dans un jeu de 52 cartes ?","choices_fr":["1/4","1/13","1/2","13/52"],"correct_index":0,"explanation_fr":"13 cœurs sur 52 cartes : $13/52 = 1/4$."},{"stem_fr":"Si $P(A) = 0{,}3$ alors $P(\\bar A) = ?$","choices_fr":["0,3","0,7","1,3","0"],"correct_index":1,"explanation_fr":"$1 - 0{,}3 = 0{,}7$."},{"stem_fr":"Pour un événement quelconque, $P(A)$ est dans :","choices_fr":["$\\mathbb{R}$","$[0, 1]$","$[-1, 1]$","$\\mathbb{N}$"],"correct_index":1,"explanation_fr":"Une probabilité est toujours entre 0 et 1."}]}]}]}'::jsonb WHERE code = 'prob_basic';

-- ===== conditional_prob =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Probabilités conditionnelles","subtitle_fr":"Conditionnement, indépendance, formule de Bayes.","sections":[{"kind":"concept","title_fr":"Définition","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"P(A | B) = \\dfrac{P(A \\cap B)}{P(B)} \\quad (P(B) > 0)","caption_fr":"« probabilité de $A$ sachant $B$ »."},{"kind":"formula","latex":"P(A \\cap B) = P(B) \\cdot P(A | B) = P(A) \\cdot P(B | A)","caption_fr":"Probabilité d''une intersection."},{"kind":"callout","tone":"insight","title_fr":"Indépendance","body_fr":"Deux événements $A$ et $B$ sont **indépendants** si $P(A \\cap B) = P(A)\\cdot P(B)$, ce qui équivaut à $P(A | B) = P(A)$."}]},{"kind":"exampleWalkthrough","title_fr":"Exemple type","eyebrow_fr":"EXEMPLE","estimated_minutes":"5","blocks":[{"kind":"example","title_fr":"Tirage successif sans remise","problem_fr":"Une urne contient 3 boules rouges et 2 noires. On en tire 2 sans remise. Quelle est la probabilité d''obtenir 2 rouges ?","steps_fr":["Premier tirage rouge : $P(R_1) = 3/5$.","Sachant $R_1$, il reste 2 rouges sur 4 : $P(R_2 | R_1) = 2/4 = 1/2$.","$P(R_1 \\cap R_2) = 3/5 \\cdot 1/2 = 3/10$."],"answer_fr":"$3/10$."},{"kind":"checkpoint","title_fr":"Conditionnelles","questions":[{"stem_fr":"$P(A | B) = ?$","choices_fr":["$P(A) \\cdot P(B)$","$P(A \\cap B) / P(B)$","$P(A) + P(B)$","$P(B)/P(A)$"],"correct_index":1,"explanation_fr":"Définition exacte."},{"stem_fr":"A et B indépendants ⟹ $P(A \\cap B) = ?$","choices_fr":["$P(A) + P(B)$","$P(A) - P(B)$","$P(A) \\cdot P(B)$","$1 - P(A)P(B)$"],"correct_index":2,"explanation_fr":"Définition de l''indépendance."}]}]}]}'::jsonb WHERE code = 'conditional_prob';

-- ===== random_variables =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Variables aléatoires","subtitle_fr":"Loi, espérance, variance, écart-type.","sections":[{"kind":"concept","title_fr":"Définition","eyebrow_fr":"CONCEPT","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une **variable aléatoire** $X$ associe un nombre à chaque issue de l''expérience aléatoire."},{"kind":"paragraph","md":"Sa **loi de probabilité** est la donnée des valeurs prises par $X$ et leurs probabilités."}]},{"kind":"concept","title_fr":"Espérance et variance","eyebrow_fr":"PARAMÈTRES","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"E(X) = \\sum_i x_i \\cdot P(X = x_i)","caption_fr":"Espérance — moyenne pondérée."},{"kind":"formula","latex":"V(X) = E((X - E(X))^2) = \\sum_i (x_i - E(X))^2 P(X = x_i)","caption_fr":"Variance."},{"kind":"formula","latex":"\\sigma(X) = \\sqrt{V(X)}","caption_fr":"Écart-type."},{"kind":"example","title_fr":"Espérance d''un dé","problem_fr":"Calcule $E(X)$ pour un dé équilibré ($X$ = numéro tiré).","steps_fr":["Chaque face : $P = 1/6$.","$E(X) = (1+2+3+4+5+6)/6 = 21/6 = 3{,}5$."],"answer_fr":"$E(X) = 3{,}5$."},{"kind":"checkpoint","title_fr":"Variables aléatoires","questions":[{"stem_fr":"L''espérance d''une v.a. représente :","choices_fr":["valeur la plus probable","moyenne pondérée des valeurs","écart-type","maximum"],"correct_index":1,"explanation_fr":"Définition de l''espérance."},{"stem_fr":"Si $X$ vaut 0 ou 1 avec $P(X=1) = p$, alors $E(X) = ?$","choices_fr":["$0$","$1$","$p$","$1-p$"],"correct_index":2,"explanation_fr":"$0 \\cdot (1-p) + 1 \\cdot p = p$."}]}]}]}'::jsonb WHERE code = 'random_variables';

-- ===== complex_basics =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Nombres complexes — forme algébrique","subtitle_fr":"Définition, opérations, conjugué, module.","sections":[{"kind":"concept","title_fr":"Définition","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"On note $i$ un nombre tel que $i^2 = -1$. Un **nombre complexe** s''écrit $z = a + ib$ avec $a, b \\in \\mathbb{R}$."},{"kind":"paragraph","md":"$a = \\text{Re}(z)$ est la **partie réelle**, $b = \\text{Im}(z)$ la **partie imaginaire**."},{"kind":"formula","latex":"\\bar z = a - ib","caption_fr":"**Conjugué** : on change le signe de la partie imaginaire."},{"kind":"formula","latex":"|z| = \\sqrt{a^2 + b^2}","caption_fr":"**Module** — distance à l''origine dans le plan complexe."},{"kind":"interactive","widget_type":"complex_plane","caption_fr":"Place $z = a + ib$ dans le plan complexe."}]},{"kind":"concept","title_fr":"Opérations","eyebrow_fr":"OPÉRATIONS","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"(a + ib) + (c + id) = (a+c) + i(b+d)","caption_fr":"Addition."},{"kind":"formula","latex":"(a + ib)(c + id) = (ac - bd) + i(ad + bc)","caption_fr":"Multiplication (utilise $i^2 = -1$)."},{"kind":"formula","latex":"\\dfrac{z_1}{z_2} = \\dfrac{z_1 \\bar z_2}{|z_2|^2}","caption_fr":"Division : multiplie haut/bas par le conjugué du dénominateur."},{"kind":"example","title_fr":"Calcul de produit","problem_fr":"Calcule $(2 + 3i)(1 - i)$.","steps_fr":["$(2)(1) + (2)(-i) + (3i)(1) + (3i)(-i)$","$= 2 - 2i + 3i - 3i^2 = 2 - 2i + 3i + 3 = 5 + i$."],"answer_fr":"$5 + i$."},{"kind":"checkpoint","title_fr":"Complexes","questions":[{"stem_fr":"Le module de $3 + 4i$ vaut :","choices_fr":["3","4","5","7"],"correct_index":2,"explanation_fr":"$\\sqrt{9 + 16} = \\sqrt{25} = 5$."},{"stem_fr":"Le conjugué de $2 - 5i$ est :","choices_fr":["$-2 + 5i$","$2 + 5i$","$-2 - 5i$","$5 + 2i$"],"correct_index":1,"explanation_fr":"On change le signe de la partie imaginaire."},{"stem_fr":"$i^2 = ?$","choices_fr":["1","−1","$i$","0"],"correct_index":1,"explanation_fr":"Définition du nombre $i$."}]}]}]}'::jsonb WHERE code = 'complex_basics';

-- ===== complex_trig =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Forme trigonométrique","subtitle_fr":"Argument, forme $re^{i\\theta}$, formules de Moivre.","sections":[{"kind":"concept","title_fr":"Module et argument","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"z = r(\\cos\\theta + i\\sin\\theta) = r e^{i\\theta}","caption_fr":"Forme **trigonométrique** (et exponentielle)."},{"kind":"formula","latex":"r = |z|, \\quad \\theta = \\arg(z) \\quad (\\text{mod } 2\\pi)","caption_fr":"Module et argument."},{"kind":"callout","tone":"insight","title_fr":"Calcul de $\\theta$","body_fr":"Si $z = a + ib$ avec $z \\ne 0$, alors $\\cos\\theta = a/r$ et $\\sin\\theta = b/r$. On choisit $\\theta$ dans $]-\\pi, \\pi]$."}]},{"kind":"concept","title_fr":"Formules de Moivre","eyebrow_fr":"MOIVRE","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"(r e^{i\\theta})^n = r^n e^{in\\theta}","caption_fr":"Puissance."},{"kind":"formula","latex":"e^{i\\alpha} \\cdot e^{i\\beta} = e^{i(\\alpha + \\beta)}, \\quad \\dfrac{e^{i\\alpha}}{e^{i\\beta}} = e^{i(\\alpha-\\beta)}","caption_fr":"Multiplication = addition des arguments."},{"kind":"example","title_fr":"Élever à la puissance","problem_fr":"Calcule $(1+i)^4$.","steps_fr":["$|1+i| = \\sqrt{2}$, $\\arg(1+i) = \\pi/4$.","$1 + i = \\sqrt{2} e^{i\\pi/4}$.","$(1+i)^4 = (\\sqrt{2})^4 \\cdot e^{i\\pi} = 4 \\cdot (-1) = -4$."],"answer_fr":"$-4$."},{"kind":"checkpoint","title_fr":"Trigo","questions":[{"stem_fr":"Argument de $i$ ?","choices_fr":["0","$\\pi/2$","$\\pi$","$2\\pi$"],"correct_index":1,"explanation_fr":"$i$ est sur l''axe imaginaire positif → $\\pi/2$."},{"stem_fr":"$|e^{i\\theta}| = ?$","choices_fr":["0","1","$\\theta$","$\\cos\\theta$"],"correct_index":1,"explanation_fr":"$|\\cos\\theta + i\\sin\\theta| = \\sqrt{\\cos^2 + \\sin^2} = 1$."}]}]}]}'::jsonb WHERE code = 'complex_trig';

-- ===== complex_geometry =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Applications géométriques des complexes","subtitle_fr":"Affixes, transformations, lignes de niveau.","sections":[{"kind":"concept","title_fr":"Affixe et transformations","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"À chaque point $M(a, b)$ du plan, on associe son **affixe** $z_M = a + ib$."},{"kind":"paragraph","md":"Transformations classiques :"},{"kind":"paragraph","md":"• **Translation** de vecteur $\\vec u$ : $z'' = z + u$."},{"kind":"paragraph","md":"• **Rotation** de centre 0, angle $\\theta$ : $z'' = e^{i\\theta} z$."},{"kind":"paragraph","md":"• **Homothétie** de centre 0, rapport $k$ : $z'' = k z$."},{"kind":"formula","latex":"|z_B - z_A| = AB \\quad ; \\quad \\arg(z_B - z_A) = (\\vec u, \\overrightarrow{AB})","caption_fr":"Distance et angle via les affixes."}]},{"kind":"exampleWalkthrough","title_fr":"Exemple : losange","eyebrow_fr":"EXEMPLE","estimated_minutes":"4","blocks":[{"kind":"example","title_fr":"Reconnaître un losange","problem_fr":"$A, B, C, D$ ont pour affixes $0, 1, 1+i, i$. Que peut-on dire de ABCD ?","steps_fr":["$|z_B - z_A| = 1$, $|z_C - z_B| = 1$, etc. — tous les côtés ont même longueur.","Les diagonales $AC$ et $BD$ sont perpendiculaires (l''une est $\\sqrt{2} e^{i\\pi/4}$, l''autre $\\sqrt{2} e^{i 3\\pi/4}$).","Donc ABCD est un **carré** (cas particulier de losange)."],"answer_fr":"ABCD est un carré."},{"kind":"checkpoint","title_fr":"Géométrie","questions":[{"stem_fr":"L''affixe du milieu de $[AB]$ avec $z_A = 1$ et $z_B = 3 + 2i$ est :","choices_fr":["$2 + i$","$1 + i$","$4 + 2i$","$3 + 2i$"],"correct_index":0,"explanation_fr":"Milieu : $(z_A + z_B)/2 = (4 + 2i)/2 = 2 + i$."}]}]}]}'::jsonb WHERE code = 'complex_geometry';

-- ===== ode_first_order =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Équations différentielles du premier ordre","subtitle_fr":"Forme $y'' = ay + b$, solutions générales.","sections":[{"kind":"concept","title_fr":"Équation $y'' = ay$","eyebrow_fr":"HOMOGÈNE","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"y'' = a y \\implies y(x) = K e^{ax}, \\quad K \\in \\mathbb{R}","caption_fr":"Solutions générales."},{"kind":"interactive","widget_type":"diff_eq_solver","caption_fr":"Saisis l''équation et teste différentes conditions initiales."},{"kind":"example","title_fr":"Croissance exponentielle","problem_fr":"Résous $y'' = 2y$ avec $y(0) = 3$.","steps_fr":["Solution générale : $y(x) = K e^{2x}$.","Condition initiale : $y(0) = K = 3$.","Donc $y(x) = 3 e^{2x}$."],"answer_fr":"$y(x) = 3 e^{2x}$."}]},{"kind":"concept","title_fr":"Équation $y'' = ay + b$","eyebrow_fr":"COMPLÈTE","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"y'' = a y + b \\implies y(x) = K e^{ax} - \\dfrac{b}{a} \\quad (a \\ne 0)","caption_fr":"Solution = solution homogène + solution particulière constante."},{"kind":"example","title_fr":"Refroidissement (loi de Newton)","problem_fr":"Résous $y'' = -y + 5$ avec $y(0) = 0$.","steps_fr":["Solution générale : $y = K e^{-x} + 5$.","$y(0) = K + 5 = 0 \\Rightarrow K = -5$.","$y(x) = -5 e^{-x} + 5 = 5(1 - e^{-x})$."],"answer_fr":"$y(x) = 5(1 - e^{-x})$."},{"kind":"checkpoint","title_fr":"ODE 1er ordre","questions":[{"stem_fr":"Solution générale de $y'' = 3y$ ?","choices_fr":["$3x$","$K e^{3x}$","$e^x + 3$","$3 e^x$"],"correct_index":1,"explanation_fr":"$y'' = ay$ ⟹ $y = K e^{ax}$."},{"stem_fr":"Si $y'' = -2y$ et $y(0) = 4$, alors $y(x) = ?$","choices_fr":["$4 e^{2x}$","$4 e^{-2x}$","$-2 e^{4x}$","$4 - 2x$"],"correct_index":1,"explanation_fr":"Solution générale $K e^{-2x}$, condition initiale donne $K = 4$."}]}]}]}'::jsonb WHERE code = 'ode_first_order';

-- ===== ode_second_order =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Équations différentielles du second ordre","subtitle_fr":"$y'''' + \\omega^2 y = 0$ et oscillateur harmonique.","sections":[{"kind":"concept","title_fr":"Cas $y'''' + \\omega^2 y = 0$","eyebrow_fr":"OSCILLATEUR","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"y'''' + \\omega^2 y = 0 \\implies y(x) = A\\cos(\\omega x) + B\\sin(\\omega x)","caption_fr":"Deux constantes d''intégration → deux conditions (souvent $y(0)$ et $y''(0)$)."},{"kind":"callout","tone":"insight","title_fr":"Forme amplitude/phase","body_fr":"On peut aussi écrire $y(x) = R\\cos(\\omega x - \\varphi)$ avec $R = \\sqrt{A^2 + B^2}$ et $\\tan\\varphi = B/A$. Plus parlant pour la physique."}]},{"kind":"exampleWalkthrough","title_fr":"Pendule simplifié","eyebrow_fr":"EXEMPLE","estimated_minutes":"5","blocks":[{"kind":"example","title_fr":"Oscillations harmoniques","problem_fr":"Résous $y'''' + 4y = 0$ avec $y(0) = 1$, $y''(0) = 0$.","steps_fr":["Ici $\\omega^2 = 4$, donc $\\omega = 2$.","Solution générale : $y(x) = A\\cos(2x) + B\\sin(2x)$.","$y(0) = A = 1$.","$y''(x) = -2A\\sin(2x) + 2B\\cos(2x)$, $y''(0) = 2B = 0 \\Rightarrow B = 0$.","Donc $y(x) = \\cos(2x)$."],"answer_fr":"$y(x) = \\cos(2x)$."},{"kind":"checkpoint","title_fr":"ODE 2nd ordre","questions":[{"stem_fr":"Solution générale de $y'''' + 9y = 0$ ?","choices_fr":["$A e^{3x}$","$A\\cos(3x) + B\\sin(3x)$","$e^{9x}$","$Ax + B$"],"correct_index":1,"explanation_fr":"$\\omega = 3$ donc oscillation de pulsation 3."}]}]}]}'::jsonb WHERE code = 'ode_second_order';

-- ===== kinematics =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Cinématique","subtitle_fr":"Position, vitesse, accélération — décrire un mouvement.","sections":[{"kind":"concept","title_fr":"Vecteurs position, vitesse, accélération","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\vec v = \\dfrac{d\\vec{OM}}{dt}, \\quad \\vec a = \\dfrac{d\\vec v}{dt} = \\dfrac{d^2 \\vec{OM}}{dt^2}","caption_fr":"Définitions cinématiques."},{"kind":"paragraph","md":"La **trajectoire** est la courbe décrite par $M$ au cours du temps. Le **mouvement** est défini par la trajectoire ET la loi horaire."},{"kind":"interactive","widget_type":"motion_simulator","caption_fr":"Joue avec position, vitesse, accélération."}]},{"kind":"concept","title_fr":"Mouvements de référence","eyebrow_fr":"TYPES","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\text{MRU} : x(t) = x_0 + v t \\quad (a = 0)","caption_fr":"Mouvement rectiligne uniforme."},{"kind":"formula","latex":"\\text{MRUA} : x(t) = x_0 + v_0 t + \\tfrac{1}{2} a t^2","caption_fr":"Mouvement rectiligne uniformément accéléré."},{"kind":"example","title_fr":"Chute libre","problem_fr":"Un objet tombe sans vitesse initiale. Quelle hauteur a-t-il parcourue à $t = 2$ s ? ($g = 10$ m/s²)","steps_fr":["MRUA avec $v_0 = 0$, $a = g = 10$ m/s².","$h = \\tfrac{1}{2} g t^2 = \\tfrac{1}{2} \\cdot 10 \\cdot 4 = 20$ m."],"answer_fr":"20 m."},{"kind":"checkpoint","title_fr":"Cinématique","questions":[{"stem_fr":"Si $\\vec a = \\vec 0$ alors le mouvement est :","choices_fr":["accéléré","uniforme","oscillant","circulaire"],"correct_index":1,"explanation_fr":"Pas d''accélération = vitesse constante = MRU."},{"stem_fr":"L''unité SI de l''accélération est :","choices_fr":["m/s","m/s²","N","J"],"correct_index":1,"explanation_fr":"Variation de vitesse par unité de temps."}]}]}]}'::jsonb WHERE code = 'kinematics';

-- ===== newtons_laws =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Lois de Newton","subtitle_fr":"Inertie, principe fondamental, action-réaction.","sections":[{"kind":"concept","title_fr":"Les trois lois","eyebrow_fr":"CONCEPT","estimated_minutes":"6","blocks":[{"kind":"paragraph","md":"**1ère loi (inertie)** : dans un référentiel galiléen, un solide isolé (ou pseudo-isolé) a un mouvement rectiligne uniforme."},{"kind":"paragraph","md":"**2nde loi (PFD)** : $\\sum \\vec F = m \\vec a$ — la somme des forces extérieures égale la masse fois l''accélération."},{"kind":"paragraph","md":"**3ème loi (action-réaction)** : si A exerce $\\vec F_{A/B}$ sur B, alors B exerce $\\vec F_{B/A} = -\\vec F_{A/B}$ sur A."},{"kind":"formula","latex":"\\sum \\vec F_{\\text{ext}} = m \\vec a","caption_fr":"Principe fondamental de la dynamique."},{"kind":"interactive","widget_type":"force_diagram","caption_fr":"Bilan des forces sur un solide."}]},{"kind":"exampleWalkthrough","title_fr":"Exemple type","eyebrow_fr":"EXEMPLE","estimated_minutes":"5","blocks":[{"kind":"example","title_fr":"Solide sur plan incliné sans frottement","problem_fr":"Solide de masse $m$ sur un plan d''inclinaison $\\alpha$, sans frottement. Trouve l''accélération.","steps_fr":["Forces : poids $\\vec P$ (vertical, vers le bas) et réaction normale $\\vec R$ (perpendiculaire au plan).","Projection sur l''axe du plan (descente positive) : $P \\sin\\alpha = m a$.","Avec $P = mg$ : $a = g \\sin\\alpha$."],"answer_fr":"$a = g\\sin\\alpha$."},{"kind":"checkpoint","title_fr":"Newton","questions":[{"stem_fr":"Le PFD s''écrit :","choices_fr":["$\\vec F = m \\vec v$","$\\sum \\vec F = m \\vec a$","$\\vec F = mg$","$\\vec a = m \\vec F$"],"correct_index":1,"explanation_fr":"Somme des forces = masse × accélération."},{"stem_fr":"Un objet en équilibre :","choices_fr":["$\\vec a = \\vec g$","$\\sum \\vec F = \\vec 0$","n''existe pas","$\\vec v = \\vec 0$ obligatoire"],"correct_index":1,"explanation_fr":"Équilibre = somme des forces nulle (peut être en MRU)."},{"stem_fr":"Action-réaction : si A pousse B avec 10 N, B pousse A avec :","choices_fr":["0 N","5 N","10 N en sens opposé","20 N"],"correct_index":2,"explanation_fr":"Même intensité, sens opposé."}]}]}]}'::jsonb WHERE code = 'newtons_laws';

-- ===== energy =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Énergie mécanique","subtitle_fr":"Énergie cinétique, potentielle, conservation.","sections":[{"kind":"concept","title_fr":"Définitions","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"E_c = \\tfrac{1}{2} m v^2","caption_fr":"**Énergie cinétique** — liée au mouvement."},{"kind":"formula","latex":"E_{pp} = m g z","caption_fr":"**Énergie potentielle de pesanteur** (z compté vers le haut)."},{"kind":"formula","latex":"E_m = E_c + E_p","caption_fr":"**Énergie mécanique totale**."}]},{"kind":"concept","title_fr":"Conservation","eyebrow_fr":"CONSERVATION","estimated_minutes":"5","blocks":[{"kind":"callout","tone":"insight","title_fr":"Système conservatif","body_fr":"Si seules des forces conservatives agissent (poids, ressort), alors $E_m$ se conserve : $\\Delta E_m = 0$."},{"kind":"formula","latex":"\\Delta E_m = W(\\text{forces non conservatives})","caption_fr":"Théorème de l''énergie mécanique."},{"kind":"example","title_fr":"Chute libre","problem_fr":"Un objet tombe d''une hauteur $h$. Sa vitesse au sol ?","steps_fr":["Au sommet : $E_c = 0$, $E_p = mgh$.","Au sol : $E_c = \\frac{1}{2} m v^2$, $E_p = 0$.","Conservation : $mgh = \\frac{1}{2} m v^2$ ⟹ $v = \\sqrt{2gh}$."],"answer_fr":"$v = \\sqrt{2gh}$."},{"kind":"checkpoint","title_fr":"Énergie","questions":[{"stem_fr":"L''énergie cinétique d''un objet de 2 kg à 5 m/s ?","choices_fr":["10 J","25 J","50 J","100 J"],"correct_index":1,"explanation_fr":"$\\frac{1}{2}\\cdot 2 \\cdot 25 = 25$ J."},{"stem_fr":"Si seul le poids travaille, l''énergie mécanique :","choices_fr":["augmente","diminue","se conserve","oscille"],"correct_index":2,"explanation_fr":"Le poids est conservatif."}]}]}]}'::jsonb WHERE code = 'energy';

-- ===== wave_properties =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Propriétés des ondes","subtitle_fr":"Onde mécanique, célérité, période, longueur d''onde.","sections":[{"kind":"concept","title_fr":"Définitions","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"Une **onde** est la propagation d''une perturbation sans transport de matière, mais avec transport d''énergie."},{"kind":"formula","latex":"v = \\lambda / T = \\lambda \\cdot f","caption_fr":"Célérité, longueur d''onde, période, fréquence."},{"kind":"interactive","widget_type":"wave","caption_fr":"Modifie période et amplitude — observe la propagation."}]},{"kind":"concept","title_fr":"Périodicité spatiale et temporelle","eyebrow_fr":"PÉRIODICITÉ","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"Une onde **progressive sinusoïdale** est doublement périodique : en temps (période $T$) et en espace (longueur d''onde $\\lambda$)."},{"kind":"formula","latex":"y(x, t) = A \\cos\\left(2\\pi\\left(\\dfrac{t}{T} - \\dfrac{x}{\\lambda}\\right)\\right)","caption_fr":"Équation d''une onde plane progressive."},{"kind":"example","title_fr":"Calcul de longueur d''onde","problem_fr":"Onde sonore à 1 kHz dans l''air (v = 340 m/s). $\\lambda = ?$","steps_fr":["$\\lambda = v / f = 340 / 1000 = 0{,}34$ m."],"answer_fr":"0,34 m = 34 cm."},{"kind":"checkpoint","title_fr":"Ondes","questions":[{"stem_fr":"Si f double, $\\lambda$ devient (à v constante) :","choices_fr":["double","inchangée","moitié","quadruple"],"correct_index":2,"explanation_fr":"$\\lambda = v/f$ : doubler f divise $\\lambda$ par 2."},{"stem_fr":"Une onde transporte :","choices_fr":["de la matière","de l''énergie","rien","des charges"],"correct_index":1,"explanation_fr":"Énergie sans transport de matière."}]}]}]}'::jsonb WHERE code = 'wave_properties';

-- ===== sound_light =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Ondes sonores et lumineuses","subtitle_fr":"Diffraction, réfraction, interférences.","sections":[{"kind":"concept","title_fr":"Diffraction","eyebrow_fr":"DIFFRACTION","estimated_minutes":"4","blocks":[{"kind":"paragraph","md":"La **diffraction** apparaît quand une onde rencontre un obstacle ou une ouverture de taille comparable à $\\lambda$. L''onde s''étale au-delà de l''obstacle."},{"kind":"formula","latex":"\\theta \\approx \\dfrac{\\lambda}{a}","caption_fr":"Demi-angle de la tâche centrale (fente de largeur $a$)."}]},{"kind":"concept","title_fr":"Réfraction","eyebrow_fr":"RÉFRACTION","estimated_minutes":"4","blocks":[{"kind":"formula","latex":"n_1 \\sin i_1 = n_2 \\sin i_2","caption_fr":"**Loi de Snell-Descartes**."},{"kind":"interactive","widget_type":"refraction_simulator","caption_fr":"Bouge l''angle d''incidence — observe l''angle réfracté."},{"kind":"example","title_fr":"Rayon air → eau","problem_fr":"Rayon arrivant à 30° sur de l''eau ($n = 1{,}33$). Angle de réfraction ?","steps_fr":["$\\sin i_2 = \\sin 30 / 1{,}33 = 0{,}5 / 1{,}33 \\approx 0{,}376$.","$i_2 \\approx 22{,}1°$."],"answer_fr":"$\\approx 22°$."},{"kind":"checkpoint","title_fr":"Optique","questions":[{"stem_fr":"La diffraction est marquée quand :","choices_fr":["$\\lambda \\gg a$","$\\lambda \\ll a$","$\\lambda \\approx a$","jamais"],"correct_index":2,"explanation_fr":"Effet visible quand l''ouverture est de l''ordre de $\\lambda$."},{"stem_fr":"Quand la lumière passe d''un milieu plus réfringent à un moins réfringent :","choices_fr":["l''angle augmente","l''angle diminue","reste identique","elle s''arrête"],"correct_index":0,"explanation_fr":"Si $n_1 > n_2$, alors $i_2 > i_1$."}]}]}]}'::jsonb WHERE code = 'sound_light';

-- ===== rc_rl_circuits =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Circuits RC et RL","subtitle_fr":"Charge/décharge d''un condensateur, établissement du courant dans une bobine.","sections":[{"kind":"concept","title_fr":"Circuit RC","eyebrow_fr":"RC","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\tau = RC","caption_fr":"**Constante de temps** RC — temps caractéristique de charge."},{"kind":"formula","latex":"u_C(t) = E (1 - e^{-t/\\tau})","caption_fr":"Charge d''un condensateur sous tension $E$."},{"kind":"formula","latex":"u_C(t) = U_0 e^{-t/\\tau}","caption_fr":"Décharge."},{"kind":"interactive","widget_type":"capacitor_charge","caption_fr":"Joue avec R et C — observe la courbe."}]},{"kind":"concept","title_fr":"Circuit RL","eyebrow_fr":"RL","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"\\tau = L/R","caption_fr":"Constante de temps RL."},{"kind":"formula","latex":"i(t) = \\dfrac{E}{R}\\left(1 - e^{-t/\\tau}\\right)","caption_fr":"Établissement du courant."},{"kind":"example","title_fr":"Calcul de constante de temps","problem_fr":"$R = 1$ kΩ, $C = 10$ µF. $\\tau = ?$","steps_fr":["$\\tau = RC = 10^3 \\cdot 10 \\cdot 10^{-6} = 10^{-2}$ s = 10 ms."],"answer_fr":"10 ms."},{"kind":"checkpoint","title_fr":"RC/RL","questions":[{"stem_fr":"Au bout de $5\\tau$, la charge atteint :","choices_fr":["50%","63%","99%","100%"],"correct_index":2,"explanation_fr":"$1 - e^{-5} \\approx 0{,}993$."},{"stem_fr":"Constante de temps d''un circuit RL :","choices_fr":["$RL$","$L/R$","$R/L$","$L+R$"],"correct_index":1,"explanation_fr":"$\\tau = L/R$."}]}]}]}'::jsonb WHERE code = 'rc_rl_circuits';

-- ===== rlc_oscillations =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Oscillations RLC","subtitle_fr":"Régimes libres, période propre, amortissement.","sections":[{"kind":"concept","title_fr":"Équation différentielle","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"LC \\dfrac{d^2 u_C}{dt^2} + RC \\dfrac{d u_C}{dt} + u_C = 0","caption_fr":"Circuit RLC série, décharge libre."},{"kind":"formula","latex":"T_0 = 2\\pi \\sqrt{LC}","caption_fr":"Période propre (cas non amorti)."},{"kind":"interactive","widget_type":"rlc","caption_fr":"Joue avec R, L, C — observe les trois régimes."}]},{"kind":"concept","title_fr":"Trois régimes","eyebrow_fr":"RÉGIMES","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Pseudo-périodique** (faible $R$) : oscillations amorties."},{"kind":"paragraph","md":"**Critique** ($R$ critique) : retour exponentiel le plus rapide possible sans oscillation."},{"kind":"paragraph","md":"**Apériodique** ($R$ grand) : retour lent à l''équilibre."},{"kind":"example","title_fr":"Période propre","problem_fr":"$L = 0{,}1$ H, $C = 10$ µF. $T_0 = ?$","steps_fr":["$T_0 = 2\\pi \\sqrt{0{,}1 \\cdot 10^{-5}} = 2\\pi \\sqrt{10^{-6}} = 2\\pi \\cdot 10^{-3}$","$\\approx 6{,}28 \\cdot 10^{-3}$ s = 6,28 ms."],"answer_fr":"≈ 6,28 ms."},{"kind":"checkpoint","title_fr":"RLC","questions":[{"stem_fr":"Période propre d''un RLC :","choices_fr":["$2\\pi \\sqrt{RC}$","$2\\pi \\sqrt{LC}$","$2\\pi RL$","$\\sqrt{L/C}$"],"correct_index":1,"explanation_fr":"$T_0 = 2\\pi\\sqrt{LC}$."},{"stem_fr":"Régime critique :","choices_fr":["oscillations entretenues","pas d''oscillation, retour le plus rapide","rien ne se passe","instable"],"correct_index":1,"explanation_fr":"Frontière entre pseudo-périodique et apériodique."}]}]}]}'::jsonb WHERE code = 'rlc_oscillations';

-- ===== acid_base =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Réactions acido-basiques","subtitle_fr":"pH, couples acide/base, équilibre acide-base.","sections":[{"kind":"concept","title_fr":"Définitions de Brønsted","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Acide** : espèce capable de céder un proton $H^+$. **Base** : espèce capable d''en capter."},{"kind":"formula","latex":"HA + H_2O \\rightleftharpoons A^- + H_3O^+","caption_fr":"Réaction acide-base d''un acide HA dans l''eau."},{"kind":"formula","latex":"\\text{pH} = -\\log [H_3O^+]","caption_fr":"Définition du pH (en mol/L)."},{"kind":"interactive","widget_type":"acid_base_ph","caption_fr":"Joue avec la concentration et le $K_a$ — lis le pH."}]},{"kind":"concept","title_fr":"Constante d''acidité $K_a$","eyebrow_fr":"KA","estimated_minutes":"5","blocks":[{"kind":"formula","latex":"K_a = \\dfrac{[A^-][H_3O^+]}{[HA]}","caption_fr":"Constante d''équilibre de l''acide HA."},{"kind":"formula","latex":"\\text{pK}_a = -\\log K_a","caption_fr":"Forme logarithmique."},{"kind":"formula","latex":"\\text{pH} = \\text{pK}_a + \\log\\dfrac{[A^-]}{[HA]}","caption_fr":"Équation d''Henderson-Hasselbalch."},{"kind":"example","title_fr":"pH d''une solution","problem_fr":"Calcule le pH d''une solution avec $[H_3O^+] = 10^{-4}$ mol/L.","steps_fr":["pH = $-\\log(10^{-4}) = 4$."],"answer_fr":"pH = 4."},{"kind":"checkpoint","title_fr":"Acido-base","questions":[{"stem_fr":"Solution avec pH = 7 :","choices_fr":["acide","basique","neutre","inconnue"],"correct_index":2,"explanation_fr":"À 25°C, pH = 7 = neutre."},{"stem_fr":"Couple $HCl/Cl^-$ : qui est l''acide ?","choices_fr":["HCl","$Cl^-$","les deux","aucun"],"correct_index":0,"explanation_fr":"HCl cède un $H^+$ pour donner $Cl^-$."},{"stem_fr":"Si $[H_3O^+] = 10^{-3}$, alors pH =","choices_fr":["1","3","7","11"],"correct_index":1,"explanation_fr":"$-\\log 10^{-3} = 3$."}]}]}]}'::jsonb WHERE code = 'acid_base';

-- ===== redox =====
UPDATE public.skills SET lesson = '{"version":2,"title_fr":"Réactions d''oxydoréduction","subtitle_fr":"Couples Ox/Red, demi-équations, piles.","sections":[{"kind":"concept","title_fr":"Définitions","eyebrow_fr":"CONCEPT","estimated_minutes":"5","blocks":[{"kind":"paragraph","md":"**Oxydation** : perte d''électrons. **Réduction** : gain d''électrons. **Réaction redox** : transfert d''électrons d''un réducteur vers un oxydant."},{"kind":"paragraph","md":"**Couple Ox/Red** : associe un oxydant et le réducteur conjugué — par ex. $Cu^{2+}/Cu$."},{"kind":"formula","latex":"Ox + n e^- \\rightleftharpoons Red","caption_fr":"Demi-équation redox."}]},{"kind":"concept","title_fr":"Piles électrochimiques","eyebrow_fr":"PILES","estimated_minutes":"5","blocks":[{"kind":"interactive","widget_type":"daniell_cell","caption_fr":"Pile Daniell : Zn + Cu²⁺ → Zn²⁺ + Cu."},{"kind":"formula","latex":"\\Delta E^\\circ = E^\\circ(\\text{cathode}) - E^\\circ(\\text{anode})","caption_fr":"Force électromotrice standard."},{"kind":"example","title_fr":"Pile Daniell","problem_fr":"Calcule la fem standard de la pile Daniell. $E^\\circ(Cu^{2+}/Cu) = 0{,}34$ V, $E^\\circ(Zn^{2+}/Zn) = -0{,}76$ V.","steps_fr":["Le cuivre est réduit (cathode), le zinc est oxydé (anode).","$\\Delta E^\\circ = 0{,}34 - (-0{,}76) = 1{,}10$ V."],"answer_fr":"1,10 V."},{"kind":"checkpoint","title_fr":"Redox","questions":[{"stem_fr":"$Zn \\to Zn^{2+} + 2e^-$ est :","choices_fr":["une réduction","une oxydation","une combustion","une dissolution"],"correct_index":1,"explanation_fr":"Perte d''électrons = oxydation."},{"stem_fr":"Dans la pile Daniell, à l''anode :","choices_fr":["Cu se dépose","Zn s''oxyde","rien","Cu²⁺ se réduit"],"correct_index":1,"explanation_fr":"Anode = oxydation = Zn → Zn²⁺ + 2e⁻."}]}]}]}'::jsonb WHERE code = 'redox';

